if value.mode == "Realtime":
	# A window anchored to midnight leaves this page empty for the first hours of
	# every day -- at 00:20 there is not one completed interval to draw, and the
	# charts, the averages and Top Production all come up blank. Realtime is a
	# rolling window instead, long enough that each interval has something to plot.
	if value.interval == "Day":
		return system.date.midnight(system.date.addDays(value.now, -29))
	elif value.interval == "Shift":
		return system.date.addDays(value.now, -7)
	else:
		return system.date.addHours(value.now, -24)

if value.mode == "Historical":
	if value.rangeDays.period != "":
		# if historical, return 12:00:00 AM of whatever day is today + rangeDays.start
		return system.date.addDays(system.date.midnight(system.date.now()),value.rangeDays.start)
	else:
		# if historical but custom time
		return value.customTime.start

